function persist(){localStorage.setItem('pragati.state',JSON.stringify({...state,chatOpen:false,profileMenu:false,notificationOpen:false,drawer:null,modal:null}));localStorage.setItem('pragati.approved',JSON.stringify(state.approved));}
function hlink(route,label,cls=''){return `<a class="${cls}" href="#${route}" data-route="${route}">${label}</a>`}
function notify(text,route='notifications',kind='info'){state.notifications.unshift({id:Date.now(),kind,text,route,time:'Just now',read:false});state.events.unshift({title:text,detail:'PRAGATI prototype activity',time:'27 Sep 2026, just now'});persist();toast(text);}
function toast(t){const x=$('#toast');x.textContent=t;x.className='toast show';clearTimeout(window._toast);window._toast=setTimeout(()=>x.className='toast',3500);}
function btn(label,action,cls='btn',attrs=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function badge(text,tone='gray'){return `<span class="badge ${tone}">${text}</span>`}
function titleblock(kicker,title,sub='',actions=''){return `<div class="page-title-row"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div><div class="actions">${actions}</div></div>`}
function stat(label,val,note='',tone=''){return `<article class="card metric ${tone}"><div class="label">${label}</div><strong>${val}</strong><small>${note}</small></article>`}
function panel(title,body,actions=''){return `<section class="card"><div class="card-head"><h2>${title}</h2>${actions}</div>${body}</section>`}
function card(title,body,extra=''){return `<section class="card card-pad ${extra}"><h2>${title}</h2>${body}</section>`}
function table(headers,rows,empty='No records to display.'){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`}
function pageStart(route){state.route=route;const links=state.role==='applicant'?applicantLinks:govLinks;return `<div class="crumb">Home <span>›</span> ${esc(titles[route]||route)}</div>`;}
function renderShell(){const gov=state.role==='government';const menu=gov?govLinks:applicantLinks;const unread=state.notifications.filter(n=>!n.read).length;return `<div class="utility"><span class="government">GOVERNMENT OF INDIA　|　MINISTRY OF COMMERCE & INDUSTRY</span><div class="utility-right"><span>National Single Window System · Prototype</span><div class="language" aria-label="Language selection">${[['en','English'],['hi','हिन्दी'],['mr','मराठी']].map(([k,l])=>`<button data-lang="${k}" class="${state.lang===k?'active':''}">${l}</button>`).join('')}</div></div></div><header class="mainhead"><a href="#home" class="identity" aria-label="PRAGATI home"><span class="seal"><svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="28" r="19" fill="none" stroke="#123f73" stroke-width="2"/><circle cx="32" cy="28" r="4" fill="#e2a143"/><path d="M32 9v38M13 28h38M18.5 14.5l27 27m0-27-27 27" stroke="#123f73" stroke-width="1.6"/><path d="M17 52h30M21 57h22" stroke="#123f73" stroke-width="2"/></svg></span><span><strong>PRAGATI</strong><small>Industrial Approval & Compliance Orchestrator</small></span></a><nav class="topnav"><a href="#home" class="${state.route==='home'?'active':''}">Home</a><a href="#about">About</a><a href="#approvals">All Approvals</a><a href="#schemes">All Schemes</a><a href="#help">Help</a></nav><div class="navtools">${btn('<span>✦</span> <span class="agent-label">Agent Mode</span>','chat','btn primary')}<button class="icon-btn" data-action="notifications" aria-label="Notifications">♧<span class="notification-dot">${unread}</span></button><div class="profile-wrap"><button class="profile-btn" data-action="profile-menu"><span class="avatar">${gov?'AO':'MS'}</span><span class="profile-name">${gov?'A. Officer':'Mukesh Sharma'}<small>${gov?'Department Officer':'Applicant'}　⌄</small></span></button>${state.profileMenu?`<div class="dropdown"><strong style="display:block;padding:8px">Switch workspace</strong><button data-action="role-applicant">Applicant View · Mukesh Chemicals</button><button data-action="role-government">Government / Department View</button><hr><button data-action="reset-demo">Reset demo data</button><button data-action="logout">Sign out of prototype</button></div>`:''}</div></div></header><nav class="mobilebar">${menu.map(([r,ic,l])=>hlink(r,`${ic} ${l}`)).join('')}</nav><div class="layout"><aside class="sidenav"><div class="sideorg"><span class="avatar">${gov?'AO':'MS'}</span><span><strong>${gov?'Officer Workspace':'Mukesh Chemicals'}</strong><small>${gov?'Maharashtra · Pune Region':'Chemical Manufacturing · Pune'}</small></span></div><div class="sidecap">${gov?'DEPARTMENT WORKSPACE':'APPLICANT WORKSPACE'}</div>${menu.map(([r,ic,l])=>hlink(r,`<span>${ic}</span>${l}${r==='notifications'&&unread?`<i>${unread}</i>`:''}`,state.route===r?'selected':'')).join('')}<div class="sidecap govlabel">QUICK ACCESS</div>${hlink('kya','<span>⌕</span>Know Your Approvals',state.route==='kya'?'selected':'')}${hlink('application','<span>＋</span>Start Application',state.route==='application'?'selected':'')}<div class="sidebottom"><span class="status-light"></span> Sandbox · Demo data only<br><small>Prototype, not an official government service</small></div></aside><main class="page" id="page"></main></div><footer class="footer"><span>PRAGATI · Industrial Approval & Compliance Orchestrator</span><span>Prototype demonstration · Fictional applicant and operational data</span><span><a href="https://www.nsws.gov.in/" target="_blank" rel="noopener">Visit official NSWS ↗</a>　·　Maharashtra</span></footer>${state.chatOpen?chatbox():''}${btn('✦ Agent Mode','chat','assistant-fab')}<div id="portal-drawer"></div><div id="portal-modal"></div>`;}
