function derivedStatus(a){if(state.approved.includes(a.id))return 'Approved';if(state.agent?.submitted?.[a.id])return 'In Review';if(a.deps.some(d=>!state.approved.includes(d)))return 'Blocked';return a.status==='In Review'||a.status==='Awaiting Documents'?'In Review':'Ready to Apply';}
function loadRoute(route){state.route=route;state.profileMenu=false;state.notificationOpen=false;persist();document.title=`${titles[route]||'PRAGATI'} | PRAGATI`;render();window.scrollTo(0,0);}
function render(){const root=$('#app');root.innerHTML=renderShell();const main=$('#page');const routes={agent:agentPage,home,about,help,dashboard,kya,roadmap,approvals:approvalsPage,schemes,documents:docsPage,verified,application,sla,inspections,risk:riskPage,precedent,government,queue:queuePage,applicant:applicantProfile,analytics,smartqueue:smartQueue,public:publicPage,notifications:notificationsPage,renewals,knowledge,integration};(routes[state.route]||home)(main);bindGlobal();}
function home(el){el.innerHTML=pageStart('home')+`<section class="hero"><div><div class="eyebrow">ONE JOURNEY · CONNECTED GOVERNMENT</div><h1>India's Single Window for Industrial Approvals — with Intelligent Orchestration</h1><p>Identify approvals, prepare documents, coordinate applications, track timelines and manage your entire approval journey from one place.</p><div class="hero-actions">${btn('Know Your Approvals　→','route-kya','btn light')}${btn('Build My Approval Roadmap　→','route-roadmap','btn gold')}${btn('View All Approvals','route-approvals','btn light')}</div></div><div class="hero-side"><strong>Built to work with India's single-window systems</strong><p>NSWS helps identify and apply. PRAGATI adds the coordination layer that shows what to do next, when, why and where a process is waiting.</p><div class="flowmini"><span>Identify</span><b>›</b><span>Sequence</span><b>›</b><span>Coordinate</span><b>›</b><span>Track</span></div></div></section><section class="agent-banner section"><div><div class="eyebrow">NEW · AGENT MODE ON NSWS</div><h2>From submitting to delegating.</h2><p>Give PRAGATI the documents. Let the agent handle the journey, remember every deadline, and keep you informed.</p></div>${btn('✦ Delegate my approvals　→','route-agent','btn gold')}</section><div class="noticebar section">PRAGATI is a demonstration prototype. Approval rules, timelines and data are illustrative. Official eligibility, regulatory interpretation and application outcomes must be confirmed with the responsible authority.</div><section class="section"><div class="section-head"><h2>How PRAGATI helps</h2>${hlink('about','How the orchestration layer works →','linkbtn')}</div><div class="features"><article class="feature"><span class="num">01</span><strong>Know What You Need</strong><p>Identify possible approvals from business, sector, location and project details.</p></article><article class="feature"><span class="num">02</span><strong>Know What Comes Next</strong><p>See a dependency-aware roadmap that exposes approvals able to progress together.</p></article><article class="feature"><span class="num">03</span><strong>Submit Right the First Time</strong><p>Review file metadata and requirements before an application is prepared.</p></article><article class="feature"><span class="num">04</span><strong>Know Where You Stand</strong><p>Track department timelines, outstanding items, inspections and delays.</p></article></div></section><section class="section grid two"><div>${panel('Central Approvals',`<p class="subtitle">Illustrative links to approval discovery resources</p><div class="approval-list section"><button class="approval-tile" data-node="peso"><span class="tileicon">◈</span><strong>PESO site approvals</strong><small>Ministry of Commerce & Industry</small></button><button class="approval-tile" data-node="environment"><span class="tileicon">♧</span><strong>Environment screening</strong><small>Environment, Forest & Climate Change</small></button><button class="approval-tile" data-node="groundwater"><span class="tileicon">◉</span><strong>Groundwater NOC</strong><small>Central Ground Water Authority</small></button></div><a href="https://www.nsws.gov.in/" target="_blank" rel="noopener">Explore central approvals at NSWS ↗</a>`)}</div><div>${panel('State Approvals',`<p class="subtitle">Maharashtra · State and local authorities</p><div class="approval-list section"><button class="approval-tile" data-node="cte"><span class="tileicon">♧</span><strong>MPCB Consent to Establish</strong><small>Maharashtra Pollution Control Board</small></button><button class="approval-tile" data-node="fire"><span class="tileicon">△</span><strong>Fire NOC</strong><small>Maharashtra Fire Services</small></button><button class="approval-tile" data-node="factory"><span class="tileicon">⌂</span><strong>Factory Plan Approval</strong><small>Directorate of Industrial Safety</small></button></div><a href="https://maitri.maharashtra.gov.in/" target="_blank" rel="noopener">Visit Maharashtra MAITRI portal ↗</a>`)}</div></section><section class="section">${panel('Government Schemes',`<div class="grid three card-pad"><div><strong>Capital support discovery</strong><p class="subtitle">Explore state and central incentives. Confirm current guidelines and eligibility directly with the scheme authority.</p></div><div><strong>Industrial policy resources</strong><p class="subtitle">Search official policy and programme sources for Maharashtra-based projects.</p></div><div><strong>Sector programmes</strong><p class="subtitle">Review industry-specific support and application windows.</p></div></div>`,hlink('schemes','View schemes →','linkbtn'))}</section><section class="section">${panel('Popular Approvals',`<div class="approval-list card-pad">${approvals.slice(1,7).map(a=>`<button class="approval-tile" data-node="${a.id}"><span class="tileicon">▤</span><strong>${a.name}</strong><small>${a.dept}</small></button>`).join('')}</div>`,hlink('approvals','Browse all approvals →','linkbtn'))}</section><section class="section grid two">${card('Know Your Approvals',`<p class="subtitle">Answer structured questions about your proposed unit. PRAGATI creates an illustrative approval list and explains its assumptions.</p>${btn('Start KYA questionnaire →','route-kya','btn primary section')}`)}${card('A coordination layer over existing systems',`<p class="subtitle">PRAGATI adds dependency sequencing, critical-path estimates, document readiness and department bottleneck views alongside existing single-window services.</p>${btn('See PRAGATI and NSWS together →','route-about','btn section')}`)}</section>`;}
function about(el){el.innerHTML=pageStart('about')+titleblock('PLATFORM OVERVIEW','From Single Window to Intelligent Orchestration','Built to work with existing single-window systems.')+`<div class="noticebar">NSWS helps identify and apply. PRAGATI adds a project-level view of what can happen next, what is waiting, and which department owns the next action.</div><div class="section">${panel('Complementary capabilities',table(['NSWS FOUNDATION','PRAGATI ORCHESTRATION LAYER'],[['Approval identification','Dependency-aware sequencing'],['Application submission','Critical path and parallel readiness'],['Document repository','Pre-submission metadata checks'],['Status tracking','Per-application SLA clocks'],['Department status updates','Delay patterns and bottleneck visibility'],['Renewal information','Renewal planning and reminders'],['Scheme discovery','Project-context scheme research prompts'],['Existing department workflows','Joint inspection coordination concept']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')))}</div><div class="section grid two">${card('Integration principle',`<p>Departments retain their existing workflow systems. An authorised connector or status feed reflects relevant application events into the orchestration layer.</p><p class="noticebar gold">All connection indicators in this prototype are simulated. No API integration or government affiliation is claimed.</p>`)}${card('Evidence and source control',`<p>Regulatory guidance should reference official sources and effective dates. A qualified reviewer verifies changes before they affect active workflows.</p><p>Current intake rules and processing durations are sample data created for demonstration.</p>`)}</div>`;}
function help(el){el.innerHTML=pageStart('help')+titleblock('HELP & SUPPORT','How to use this demonstration','Explore the applicant workflow, then switch to the department workspace.')+`<div class="grid two">${card('Three-minute demonstration',`<ol><li>Open Know Your Approvals and inspect the structured intake.</li><li>Submit the seeded chemical project profile.</li><li>Open the roadmap and inspect an approval node.</li><li>Simulate a document validation or department status update.</li><li>Use the profile menu to switch to Department View.</li></ol>`)}${card('Prototype limitations',`<ul><li>No government service is connected. Applications do not leave this browser.</li><li>All 17 approval examples and risk/timeline estimates are illustrative.</li><li>AI/OCR outcomes are simulated; there is no document extraction service.</li><li>Role switching is a demo view, not authentication or access control.</li><li>Scheme cards link to official starting points and do not confirm eligibility.</li></ul>`)}</div><div class="section">${panel('Official reference links',`<div class="card-pad">${hlink('home','Return to PRAGATI home')}<p><a href="https://www.nsws.gov.in/" target="_blank" rel="noopener">National Single Window System ↗</a></p><p><a href="https://www.nsws.gov.in/portal/user-guide" target="_blank" rel="noopener">NSWS User Guide ↗</a></p><p><a href="https://maitri.maharashtra.gov.in/" target="_blank" rel="noopener">Maharashtra MAITRI ↗</a></p></div>`)}</div>`;}
function dashboard(el){const done=8,open=8,ready=approvals.filter(a=>derivedStatus(a)==='Ready to Apply');el.innerHTML=pageStart('dashboard')+titleblock('APPLICANT WORKSPACE','My Dashboard','Chemical Manufacturing Unit — Pune, Maharashtra',`<select id="project-switch" class="btn" aria-label="Select project"><option ${state.project==='mukesh'?'selected':''}>Mukesh Chemicals — Pune</option><option ${state.project==='rahul'?'selected':''}>Rahul Foods — Pune</option></select>`)+`<div class="grid four">${stat('OPEN APPLICATIONS','8','Across central and state departments')}${stat('APPROVED','4','Four approvals recorded', 'highlight')}${stat('RENEWALS DUE','2','Next deadline: 28 Nov 2026')}${stat('INCENTIVES TO REVIEW','5','Potential programme matches')}</div><section class="section">${panel('Approval Journey',`<div class="card-pad"><div style="display:flex;justify-content:space-between;gap:12px"><strong>8 of 17 approvals completed</strong>${hlink('roadmap','View intelligent roadmap →')}</div><div class="progressbar section"><span style="width:47%"></span></div><div class="section statusline"><span>${badge('8 Completed','green')}</span><span>${badge('5 Ready to apply','blue')}</span><span>${badge('2 In progress','amber')}</span><span>${badge('2 Waiting','gray')}</span></div></div>`)}</section><section class="section grid two"><div>${panel('Action Required',`<div class="card-pad"><div class="docrow"><div><strong>Fire NOC document expires in 62 days</strong><small>Renew before next review stage</small></div>${badge('Attention','amber')}</div><div class="docrow"><div><strong>MPCB application awaiting document</strong><small>Upload pollution control proposal</small></div>${badge('Applicant action','blue')}</div><div class="docrow"><div><strong>Building Plan approval in progress</strong><small>Planning department review · 2 days beyond illustrative SLA</small></div>${badge('SLA at risk','red')}</div><div class="docrow"><div><strong>Factory Licence is approaching SLA</strong><small>Department review period: 15 / 18 days</small></div>${badge('High priority','amber')}</div></div>`,hlink('sla','View all actions →','linkbtn'))}</div><div>${panel('Current Critical Path',`<div class="card-pad"><div class="timeline"><div class="timeline-item"><small>COMPLETED</small><strong>Land / Site Verification</strong></div><div class="timeline-item"><small>IN PROGRESS · MPCB</small><strong>Consent to Establish</strong><p>Current critical-path item · 12 / 15 days</p></div><div class="timeline-item"><small>WAITING ON CTE + BUILDING PLAN</small><strong>Factory Licence</strong></div><div class="timeline-item"><small>FINAL READINESS</small><strong>Operational approval sequence</strong></div></div><div class="noticebar gold">Illustrative timeline: current estimate 42 days. Parallel scenario estimate 31 days. Actual processing times vary by authority and project.</div></div>`,hlink('roadmap','Open roadmap →','linkbtn'))}</div></section><section class="section grid two"><div>${panel('Upcoming Deadlines',table(['ITEM','DUE DATE','REMAINING'],[['Fire NOC renewal','28 Nov 2026',badge('18 days','amber')],['MPCB Consent renewal','15 Dec 2026',badge('35 days','blue')],['Factory Licence renewal','15 Jan 2027',badge('66 days','blue')]].map(r=>`<tr><td>${r[0]}</td><td class="date">${r[1]}</td><td>${r[2]}</td></tr>`).join('')),hlink('renewals','Manage renewals →','linkbtn'))}</div><div>${panel('Recent Activity',`<div class="card-pad"><div class="timeline">${state.events.slice(0,4).map(e=>`<div class="timeline-item"><small>${esc(e.time)}</small><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p></div>`).join('')}</div></div>`,hlink('notifications','View notifications →','linkbtn'))}</div></section><section class="section grid two">${card('Verified information available',`<p>Use your verified company and project details to reduce repeated data entry.</p>${btn('Review verified information →','route-verified','btn')}`)}${card('Maharashtra support schemes',`<p>Five programme categories may be worth reviewing for this project. The prototype does not determine scheme eligibility.</p>${btn('Review scheme sources →','route-schemes','btn')}`)}</section>`;const sw=$('#project-switch');sw.onchange=()=>{state.project=sw.selectedIndex?'rahul':'mukesh';toast(state.project==='rahul'?'Rahul Foods demo selected.':'Mukesh Chemicals demo selected.');};}
function kya(el){const s=state.kyaStep;const ind=state.kyaAnswers?.industry||(state.project==='rahul'?'Food Processing':'Chemicals');const steps=['Business & location','Project details','Infrastructure & risk','Review'];const fields=[`<div class="formgrid"><label class="field">Business type<select name="business"><option>New Industrial Unit</option><option>Expansion of existing unit</option><option>Commercial establishment</option></select></label><label class="field">State<select><option>Maharashtra</option></select></label><label class="field">District<select><option>Pune</option><option>Nashik</option><option>Nagpur</option><option>Thane</option></select></label><label class="field">Industry<select><option ${ind==='Chemicals'?'selected':''}>Chemicals</option><option ${ind==='Food Processing'?'selected':''}>Food Processing</option><option ${ind==='Textiles'?'selected':''}>Textiles</option><option ${ind==='Engineering'?'selected':''}>Engineering</option></select></label><label class="field">Business stage<select><option>Pre-establishment</option><option>Construction</option><option>Pre-operation</option><option>Expansion</option></select></label></div>`,`<div class="formgrid"><label class="field">Project size<select><option>Medium</option><option>Small</option><option>Large</option></select></label><label class="field">Investment range<select><option>₹25–50 Crore</option><option>Below ₹1 Crore</option><option>₹1–25 Crore</option><option>Above ₹50 Crore</option></select></label><label class="field">Proposed employment<select><option>100–250</option><option>1–9</option><option>10–49</option><option>50–99</option><option>Above 250</option></select></label><label class="field">Land status<select><option>Industrial land</option><option>Leased private land</option><option>Owned private land</option><option>Land not finalised</option></select></label></div>`,`<div class="grid two"><div><label class="field">Pollution category</label><div class="radio-row section">${['Red','Orange','Green','Not determined'].map((x,i)=>`<label class="radio-option"><input type="radio" name="pollution" value="${x}" ${i===0?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div><label class="field">Project requirements</label><div class="checkrow section">${[['construction','Construction required'],['fire','Fire safety review'],['water','Industrial water'],['fdi','Foreign investment']].map(([k,l],i)=>`<label class="checkitem"><input type="checkbox" ${i<3?'checked':''}> ${l}</label>`).join('')}</div></div></div>`,`<div class="noticebar gold">The proposed result is a demonstration. Applicability varies by process, threshold, jurisdiction and the rules in force. Review each approval with its issuing authority before filing.</div><div class="section"><strong>Project profile</strong><p>${state.project==='rahul'?'Small food business · Maharashtra · Pune · Food Processing · Green category · New industrial premises':`New industrial unit · Maharashtra · Pune · ${esc(ind)} · ${esc(state.kyaAnswers?.investment||'₹25–50 crore')} · ${esc(state.kyaAnswers?.employment||'100–250')} employees · ${esc(state.kyaAnswers?.pollution||'Red')} pollution category · ${esc(state.kyaAnswers?.land||'Industrial land')}`}</p></div>`];el.innerHTML=pageStart('kya')+titleblock('KNOW YOUR APPROVALS','Tell us about your project','Structured project details help identify possible approvals and build your next-step roadmap.')+`<div class="noticebar">This guided questionnaire follows the Know Your Approvals pattern used by single-window systems and adds a dependency and readiness view.</div><div class="kya-layout section"><section class="card"><div class="steps">${steps.map((t,i)=>`<span class="${i===s?'active':''}">${i+1}　${t}</span>`).join('')}</div><form id="kya-form" class="card-pad"><h2>${steps[s]}</h2><div class="section">${fields[s]}</div><div class="actions section" style="justify-content:space-between">${s?btn('← Back','kya-back','btn'):''}${s<3?btn('Continue →','kya-next','btn primary'):btn('Analyse requirements →','kya-submit','btn primary')}</div></form></section><aside class="card card-pad"><div class="eyebrow">PROJECT PROFILE</div><h2>${state.project==='rahul'?'Rahul Foods · Artisan Bakery':'New chemical unit'}</h2><div class="keyval"><span>Location</span><strong>Pune, Maharashtra</strong></div><div class="keyval"><span>Industry</span><strong>${esc(ind)}</strong></div><div class="keyval"><span>Project stage</span><strong>Pre-establishment</strong></div><div class="keyval"><span>Risk indicator</span>${badge(state.project==='rahul'||state.kyaAnswers?.pollution==='Green'?'Low':'High',state.project==='rahul'||state.kyaAnswers?.pollution==='Green'?'green':'red')}</div><div class="noticebar gold section">Possible approvals are based on simplified prototype rules. They are not a legal determination.</div></aside></div>`;}
function roadmap(el){const focused=state.project==='rahul';const graphNodes=focused?approvals.filter(a=>['land','factory-plan','fire','electricity','labour','water'].includes(a.id)):approvals;const ready=graphNodes.filter(a=>derivedStatus(a)==='Ready to Apply').length;const total=graphNodes.length;el.innerHTML=pageStart('roadmap')+titleblock('PROJECT ROADMAP','Your Intelligent Approval Roadmap',`Based on the current project profile, ${total} approvals / registrations may apply.`,`${btn('Export roadmap ↓','roadmap-export','btn')}${btn('Continue an application →','route-application','btn primary')}`)+`<div class="grid two"><div class="noticebar gold"><strong>Risk Level: ${focused?'LOW':'HIGH'}</strong><br>${focused?'Small food business profile with a Green category indication in this demo.':'Chemical manufacturing, Red category pollution and a medium-scale industrial project increase review requirements in this demonstration.'}</div><div class="noticebar">${badge(`${ready} approvals ready to start`,'blue')} Select a roadmap node to see documents, owner department and the next action.</div></div><div class="grid four section">${stat('Approvals identified',String(total),'Applicability needs official verification')}${stat('Ready to apply',ready,'Dependencies completed','')}${stat('Critical path estimate',focused?'18 days':'42 days','Illustrative sequential scenario')}${stat('Parallel scenario',focused?'14 days':'31 days',focused?'Potential estimate difference: 4 days':'Potential estimate difference: 11 days','highlight')}</div><div class="noticebar gold section">Estimated from demonstration workflow dependencies and illustrative processing durations. Not a legally guaranteed timeline or promise. Actual authority queues, applicant responses and inspection slots affect elapsed time.</div><section class="card section"><div class="card-head"><div><h2>Approval dependency graph</h2><p>Independent reviews can proceed together when prerequisites allow.</p></div><span class="critical-tag">◇ CRITICAL PATH</span></div><div class="graph-shell"><div class="roadmap"><div class="connector"></div><div class="criticalline"></div>${[['land','root'],['factory-plan','branch-a'],['cte','branch-b'],['factory','branch-c'],['water','branch-d'],['peso','branch-e'],['fire','mid-a'],['cto','mid-b'],['licence','branch-c'],['electricity','branch-d'],['boiler','branch-e'],['hazard','branch-b'],['groundwater','extr'],['labour','branch-a'],['environment','branch-e'],['inspection','mid-b'],['final','final']].map(([id,pos],i)=>{const a=approvals.find(a=>a.id===id),s=derivedStatus(a),tone=state.approved.includes(id)?'done':s==='Ready to Apply'?'ready':s==='In Review'?'progress':a.status==='Delayed'?'delayed':'blocked';return `<button class="stage ${pos} ${tone}" data-node="${id}" aria-label="${a.name}, ${s}"><strong>${state.approved.includes(id)?'✓ ':s==='Ready to Apply'?'● ':s==='In Review'?'◷ ':'○ '}${a.name}</strong><small>${a.dept.split('·')[0]} · ${s}</small></button>`;}).join('')}</div><div class="legend section"><span><i style="background:#55a36e"></i>Completed</span><span><i style="background:#3984b8"></i>Ready to start</span><span><i style="background:#d3a441"></i>In progress</span><span><i style="background:#aeb8c1"></i>Blocked by dependency</span><span><i style="background:#c44c42"></i>Delayed / SLA risk</span><span class="critical-tag">Critical path</span></div></div><div class="card-head"><span class="subtitle">${total} approval nodes · ${graphNodes.reduce((n,a)=>n+a.deps.filter(d=>graphNodes.some(x=>x.id===d)).length,0)} prerequisite relationships · graph revision 1</span><span class="badge gray">All rules shown are illustrative</span></div></section><section class="section grid two"><div>${panel('Ready to start',`<div class="card-pad">${approvals.filter(a=>derivedStatus(a)==='Ready to Apply').slice(0,5).map(a=>`<div class="docrow"><div><strong>${a.name}</strong><small>${a.dept} · estimate ${a.days} days</small></div>${btn('View →',`node:${a.id}`,'linkbtn')}</div>`).join('')}</div>`)}</div><div>${panel('Critical path',`<div class="card-pad"><div class="timeline"><div class="timeline-item"><small>COMPLETED</small><strong>Land / Site Verification</strong></div><div class="timeline-item"><small>CURRENT BOTTLENECK</small><strong>MPCB Consent to Establish</strong><p>12 / 15 illustrative SLA days</p></div><div class="timeline-item"><small>DEPENDENT REVIEWS</small><strong>Factory Licence → Final readiness</strong></div></div><p class="noticebar gold">Potential 11-day reduction assumes independent reviews can run in parallel without queue or rework.</p></div>`)}</div></section><div class="section">${panel('NSWS foundation + PRAGATI orchestration',`<div class="card-pad grid two"><div><h3>Single-window foundation</h3><p>Approval identification · application submission · document repository · status tracking · renewals</p></div><div><h3>Orchestration layer</h3><p>Dependency sequence · critical path · concurrent readiness · document pre-validation · per-application SLA · inspection coordination · bottleneck intelligence</p></div></div>`)}</div>`;}
function nodeDrawer(id){const a=approvals.find(x=>x.id===id);if(!a)return;const status=derivedStatus(a),tone=state.approved.includes(a.id)?'green':status==='Ready to Apply'?'blue':status==='In Review'?'amber':'gray';const docrows=a.docs.map((d,i)=>{const exists=state.documents.find(x=>x.name.toLowerCase().includes(d.toLowerCase().split(' ')[0])&&x.verified);return `<div class="docrow"><div><strong>${d}</strong><small>${exists?'✓ Uploaded and metadata checked':'Required before submission'}${exists?` · ${exists.expiry}`:''}</small></div><button class="linkbtn" data-action="doc-detail" data-doc="${esc(d)}">Where do I get this? →</button></div>`;}).join('');const actions=status==='Ready to Apply'?`${btn('Apply Now →','route-application','btn primary')}${btn('Mark application submitted','simulate-submit','btn',`data-node-id="${a.id}"`)}`:status==='In Review'?btn('View SLA clock','route-sla','btn primary'):status==='Blocked'?btn('View blocking dependencies','node-blockers','btn'):btn('View application record','route-applications','btn');openDrawer(`<div class="drawer-head"><button class="icon-btn" data-action="close-drawer" aria-label="Close">×</button><div class="eyebrow">${a.type} APPROVAL · ${a.stage.toUpperCase()}</div><h2>${a.name}</h2>${badge(status,tone)}</div><div class="drawer-body"><div class="drawer-section"><h3>Department & service details</h3><div class="keyval"><span>Department</span><strong>${a.dept}</strong></div><div class="keyval"><span>Stage</span><strong>${a.stage}</strong></div><div class="keyval"><span>Estimated processing</span><strong>${Math.max(5,a.days-4)}–${a.days+4} working days</strong></div><div class="keyval"><span>Illustrative service SLA</span><strong>${a.sla} working days</strong></div><div class="keyval"><span>Applicability source</span><strong>${a.source}</strong></div></div><div class="drawer-section"><h3>Prerequisites</h3>${a.deps.length?a.deps.map(d=>{const x=approvals.find(x=>x.id===d);return `<div class="docrow"><div><strong>${x.name}</strong><small>${state.approved.includes(d)?'Prerequisite complete':'Must be completed first'}</small></div>${badge(state.approved.includes(d)?'Complete':'Waiting',state.approved.includes(d)?'green':'gray')}</div>`}).join(''):'<p>No prerequisite in this demonstration workflow.</p>'}</div><div class="drawer-section"><h3>Required documents</h3><p class="subtitle">Select a document to see its source and validation status.</p>${docrows}${btn('Open My Documents','route-documents','btn section')}</div><div class="drawer-section"><p class="noticebar gold">PRAGATI applicability, dependency and SLA details are illustrative. Confirm applicable requirements on the responsible department’s official portal.</p></div><div class="actions section">${actions}</div></div>`);}
function approvalsPage(el){el.innerHTML=pageStart('approvals')+titleblock('APPROVAL DIRECTORY','All Approvals','Illustrative central, state and local approval catalogue.')+`<div class="tabs">${['All','Central','State','Joint'].map(x=>`<button class="tab ${state.approvalFilter===x||(!state.approvalFilter&&x==='All')?'active':''}" data-filter-approvals="${x}">${x}</button>`).join('')}</div><div id="approval-directory" class="approval-list">${approvals.filter(a=>!state.approvalFilter||state.approvalFilter==='All'||a.type.toLowerCase()===state.approvalFilter.toLowerCase()).map(a=>`<button class="approval-tile" data-node="${a.id}"><span class="tileicon">${a.type==='Central'?'◈':'▤'}</span><strong>${a.name}</strong><small>${a.dept}</small><span class="section">${badge(derivedStatus(a),a.tone)}</span></button>`).join('')}</div><div class="noticebar gold section">Prototype directory only. For authoritative requirements and filings, consult the official government portals.</div>`;}
function schemes(el){const items=[['Maharashtra Package Scheme of Incentives','State industrial incentive reference','Industrial policy resource','Official link','https://maitri.maharashtra.gov.in/'],['Technology Upgradation Support','Illustrative discovery category','Potential relevance: machinery and eligible investments','Review current scheme rules','https://www.nsws.gov.in/'],['MSME Credit Guarantee','Central scheme discovery','Potential relevance depends on MSME classification','Check current programme details','https://www.nsws.gov.in/'],['Energy Efficiency Support','Illustrative discovery category','Potential relevance depends on facility and equipment','Verify eligibility and open windows','https://www.maitri.maharashtra.gov.in/'],['Sector Modernisation Programme','Industrial support discovery','Chemical and food sectors shown for research only','Review official scheme directory','https://www.nsws.gov.in/']];const visible=items.filter(x=>state.schemeFilter==='All'||(state.schemeFilter==='Maharashtra'?x[0].includes('Maharashtra'):state.schemeFilter==='Matched to profile'?x[0].includes('Industrial')||x[0].includes('Energy'):true));el.innerHTML=pageStart('schemes')+titleblock('GOVERNMENT SCHEMES','Schemes & Incentives','Discover programmes that may be relevant to a project profile.')+`<div class="noticebar gold">The prototype shows scheme discovery categories and official portal links. It does not verify eligibility, benefit amounts, application windows, or government approval.</div><div class="tabs section">${['All','Maharashtra','Matched to profile'].map(x=>`<button class="tab ${state.schemeFilter===x?'active':''}" data-scheme-filter="${x}">${x}</button>`).join('')}</div><div class="grid three">${visible.map((x,i)=>`<article class="card card-pad"><div class="eyebrow">${i%2?'STATE RESOURCE':'CENTRAL / STATE REFERENCE'}</div><h2 class="section">${x[0]}</h2><p class="subtitle">${x[1]}</p><p>${x[2]}</p><div class="noticebar">${x[3]}</div><div class="section"><a href="${x[4]}" target="_blank" rel="noopener">Open official reference ↗</a></div>${btn('Save to research list','save-scheme','btn small section')}</article>`).join('')}</div><section class="section">${panel('Information source status',`<div class="card-pad"><p>NSWS and Maharashtra MAITRI are reference portals only. Scheme records and profile matches in this demonstration have no verified source entries attached.</p><p class="subtitle">For production, every displayed programme requires an official source URL, publication or effective date, human reviewer and verified eligibility fields.</p></div>`)}</section>`;}
function docsPage(el){const docs=state.documents.filter(d=>state.docFilter==='All Documents'||(state.docFilter==='Verified'&&d.status==='Verified')||(state.docFilter==='Needs Attention'&&d.status==='Needs attention')||(state.docFilter==='Expiring Soon'&&d.status==='Expiring soon')||(state.docFilter==='Expired'&&d.status==='Expired'));const filters=['All Documents','Verified','Needs Attention','Expiring Soon','Expired'];el.innerHTML=pageStart('documents')+titleblock('DOCUMENT VAULT','My Documents','Document reuse and pre-validation status across project applications.',btn('＋ Upload Document','upload-doc','btn primary'))+`<div class="noticebar">Upload is simulated. The prototype records the filename and document metadata only; it does not store the file bytes or send them to a government department. OCR feedback is simulated and does not establish document authenticity or official acceptance.</div><div class="grid four section">${stat('All documents',state.documents.length,'In this project vault')}${stat('Verified',state.documents.filter(d=>d.status==='Verified').length,'Prototype checks complete')}${stat('Needs attention',state.documents.filter(d=>d.status==='Needs attention').length,'Resolve before reuse')}${stat('Expiry approaching',state.documents.filter(d=>d.status==='Expiring soon').length,'Review renewal dates')}</div><div class="tabs section">${filters.map(f=>`<button class="tab ${state.docFilter===f?'active':''}" data-doc-filter="${f}">${f}</button>`).join('')}</div><section class="card">${panel('Documents available to your applications',table(['DOCUMENT','TYPE','UPLOADED','VERIFICATION','EXPIRY','USED BY',''],docs.map(d=>`<tr><td><button class="linkbtn" data-doc-detail="${esc(d.name)}"><strong>${esc(d.name)}</strong></button></td><td>${esc(d.type)}</td><td>${d.uploaded}</td><td>${badge(d.status,d.status==='Verified'?'green':d.status==='Expiring soon'?'amber':'red')}</td><td>${d.expiry}</td><td>${d.uses} applications</td><td>${btn('Details','doc:'+d.id,'linkbtn')}</td></tr>`).join('')))}</section><section class="section grid two">${card('AI + OCR Validation · simulated',`<p>File metadata checks are local. The validation sequence shown to judges is a simulation for product exploration.</p><div class="timeline"><div class="timeline-item"><strong>Document type identified</strong></div><div class="timeline-item"><strong>Name and registration number checked</strong></div><div class="timeline-item"><strong>Required fields detected</strong></div><div class="timeline-item"><strong>Expiry date compared with project record</strong></div></div><p class="noticebar gold">A production OCR service requires consent, secure processing and human review for uncertain extractions.</p>`)}${card('Tell once. Reuse with consent.',`<p>Verified company and land fields can prefill multiple application forms after the applicant confirms their use.</p>${btn('Review verified information','route-verified','btn')}`)}</section>`;}
function verified(el){const vals=[['Company Name','Mukesh Chemicals Pvt. Ltd.','MCA company incorporation certificate','12 Sep 2026'],['PAN','AABCM4821K','PAN document · locally recorded sample','12 Sep 2026'],['GSTIN','27AABCM4821K1Z5','GST registration certificate','12 Sep 2026'],['Registered Address','Plot 18, MIDC Chakan Phase II, Pune, Maharashtra','Land lease agreement','15 Sep 2026'],['Promoter Details','Mukesh Sharma · Managing Director','Incorporation filing','12 Sep 2026'],['Land Details','Industrial Plot 18, Chakan MIDC · Leasehold','Lease agreement · applicant uploaded','15 Sep 2026'],['Project Details','Chemical Manufacturing Unit · ₹35 Crore · 150 employees','Applicant declaration','27 Sep 2026']];el.innerHTML=pageStart('verified')+titleblock('VERIFIED INFORMATION','Tell once. Reuse where needed.','Review project details available to prefill your next application.')+`<div class="noticebar">The prototype labels sample fields as verified to demonstrate user experience. The source documents and verification authority are fictional demo data. No government identity lookup is performed.</div><section class="card section">${panel('Company and project profile',table(['FIELD','RECORDED VALUE','SOURCE','VERIFICATION DATE','STATUS'],vals.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${badge('✓ Verified','green')}</td></tr>`).join('')))}</section><div class="section grid two">${card('Available to this application',`<p>Company details, PAN, GSTIN and registered address can be prefilled in the application form.</p><label class="checkitem"><input type="checkbox" id="consent-check" checked> I agree to reuse these fields for this application</label>${btn('Use Verified Data →','route-application','btn primary section')}`)}${card('Access history',`<div class="timeline"><div class="timeline-item"><small>27 SEP 2026</small><strong>Profile viewed by Mukesh Sharma</strong><p>Applicant workspace · local prototype</p></div><div class="timeline-item"><small>15 SEP 2026</small><strong>Land address added</strong><p>Applicant uploaded a lease record</p></div><div class="timeline-item"><small>12 SEP 2026</small><strong>Organisation details entered</strong><p>Sample profile setup</p></div></div>`)}</div>`;}
const appSteps=['Applicant Details','Project Details','Technical Details','Documents','Declaration','Review & Submit'];
function application(el){const s=state.appStep;if(state.appSubmitted){el.innerHTML=pageStart('application')+`<section class="card card-pad" style="max-width:720px;margin:45px auto"><div class="eyebrow">DEMO APPLICATION</div><h1>Application prepared</h1><p>This prototype prepared a local application record. Nothing has been submitted to a government portal.</p><div class="noticebar">Demo reference: MH-CTE-DRAFT-20481<br>MPCB Consent to Establish · Applicant: Mukesh Chemicals Pvt. Ltd.</div><div class="section">${btn('View approval roadmap →','route-roadmap','btn primary')}${btn('Back to dashboard','route-dashboard','btn section')}</div></section>`;return;}const content=[`<div class="formgrid"><label class="field"><span class="help-line">Legal entity name <button class="field-help" data-help="This field requires the legal name exactly as recorded in your Certificate of Incorporation.">?</button></span><input value="Mukesh Chemicals Pvt. Ltd."></label><label class="field"><span class="help-line">Applicant / authorised signatory <button class="field-help" data-help="Enter the name of the person authorised to submit this application on behalf of the company.">?</button></span><input value="Mukesh Sharma"></label><label class="field">PAN<input value="AABCM4821K"></label><label class="field">GSTIN<input value="27AABCM4821K1Z5"></label></div><div class="noticebar section">${btn('Use verified data','use-verified','btn small')} Profile fields prefilled from the project record. Confirm every value before a real submission.</div>`,`<div class="formgrid"><label class="field">Project name<input value="Chemical Manufacturing Unit"></label><label class="field">Project district<input value="Pune, Maharashtra"></label><label class="field">Proposed investment<input value="₹35 Crore"></label><label class="field">Proposed employment<input value="150"></label><label class="field">Land details<input value="Industrial Plot 18, Chakan MIDC"></label></div>`,`<div class="formgrid"><label class="field"><span class="help-line">Manufacturing process <button class="field-help" data-help="Describe the main manufacturing steps and inputs. Attach a process-flow diagram in the document section.">?</button></span><textarea>Speciality chemical formulation and blending</textarea></label><label class="field">Pollution category<select><option>Red</option><option>Orange</option><option>Green</option></select></label><label class="field">Water demand<input value="25 kilolitres per day"></label><label class="field">Waste treatment proposal<textarea>Effluent treatment system proposed for process wastewater.</textarea></label></div>`,`<div class="docrow"><div><strong>Project report</strong><small>PDF · 3.4 MB · Verified in demo vault</small></div>${badge('Ready','green')}</div><div class="docrow"><div><strong>Land Lease Agreement</strong><small>PDF · 1.2 MB · Verified</small></div>${badge('Ready','green')}</div><div class="docrow"><div><strong>Pollution control proposal</strong><small>Required for this application</small></div>${badge('Missing','amber')}</div>${btn('Open Document Vault','route-documents','btn section')}`,`<label class="checkitem"><input type="checkbox" checked> I confirm that the information provided is complete and accurate to the best of my knowledge.</label><p class="subtitle section">An authorised signatory must confirm the declaration before submitting through the relevant official portal.</p>`,`<div class="noticebar gold">Review all details and attachments. This demonstration saves a local draft only. The submit action does not transmit data.</div><div class="keyval"><span>Approval</span><strong>MPCB Consent to Establish</strong></div><div class="keyval"><span>Applicant</span><strong>Mukesh Chemicals Pvt. Ltd.</strong></div><div class="keyval"><span>Attachments</span><strong>2 ready · 1 missing (demo)</strong></div>`];el.innerHTML=pageStart('application')+titleblock('APPLICATION FORM','MPCB Consent to Establish','Demonstration form · Reference MH-CTE-DRAFT-20481')+`<div class="noticebar">Use official department portals for real filings. “Save draft” and “Prepare application” below update only the prototype.</div><div class="grid" style="grid-template-columns:220px 1fr;align-items:start;gap:16px"><nav class="card formsteps">${appSteps.map((n,i)=>`<button class="${s===i?'active':i<s?'done':''}" data-appstep="${i}">${i<s?'✓':' '+(i+1)+' '}　${n}</button>`).join('')}</nav><section class="card"><div class="card-head"><h2>${appSteps[s]}</h2><button class="btn small" data-action="chat">✦ Ask Agent</button></div><div class="card-pad">${content[s]}</div><div class="card-head" style="justify-content:space-between"><button class="btn" data-action="app-back" ${s===0?'disabled':''}>← Back</button><span class="subtitle">Step ${s+1} of ${appSteps.length}</span>${s<5?btn('Save & continue →','app-next','btn primary'):btn('Prepare application','app-finish','btn primary')}</div></section></div>`;}
function sla(el){const rows=[['MH-CTE-20481','MPCB Consent to Establish','MPCB',12,15,'Under Review'],['MH-BP-20496','Building Plan Approval','Planning',17,15,'SLA Breached'],['MH-FACT-20506','Factory Licence','Factories',15,18,'At Risk'],['MH-FIRE-20475','Fire NOC','Fire Services',10,12,'At Risk'],['MH-WTR-20471','Industrial Water','MIDC',5,12,'Under Review'],['MH-PESO-20492','PESO Site Approval','PESO',4,21,'Under Review']];el.innerHTML=pageStart('sla')+titleblock('SERVICE LEVEL MONITORING','SLA Clock & Delay Intelligence','Elapsed times and risk alerts for the fictional demonstration applications.',btn('Advance demo clock +1 day','advance-clock','btn'))+`<div class="noticebar gold">SLA figures in this screen are sample operating data for the prototype. They are not official service commitments or live application status.</div><div class="grid four section">${stat('SLA at risk','8','Within 20% of illustrative limit')}${stat('SLA breached','4','Requires officer review')}${stat('Average processing','11.6 days','Across fictional sample records')}${stat('Queries raised','6','Sample open applicant queries')}</div><section class="card section">${panel('Application-level SLA clocks',table(['APPLICATION','DEPARTMENT','ELAPSED','ILLUSTRATIVE SLA','TIME REMAINING','STATUS','ACTION'],rows.map(r=>{const remain=r[4]-r[3];return `<tr><td><strong>${r[0]}</strong><small>${r[1]}</small></td><td>${r[2]}</td><td>${r[3]} days</td><td>${r[4]} days</td><td>${remain>0?remain+' days':'Breach by '+Math.abs(remain)+' days'}</td><td>${badge(r[5],r[5]==='SLA Breached'?'red':r[5]==='At Risk'?'amber':'blue')}</td><td>${btn('Details',`sla:${r[0]}`,'linkbtn')}</td></tr>`}).join('')))}</section><section class="section grid two">${card('Delay intelligence',`<h3>Current delay context</h3><p>Building Plan Approval exceeds the sample service limit by 2 days. MPCB CTE has 3 illustrative SLA days remaining.</p>${btn('View bottleneck analytics →','route-analytics','btn')}`)}${card('Escalation draft',`<p>Prepare an escalation note with the application, elapsed time and query history for officer review.</p>${btn('Draft escalation note','escalation','btn')}`)}</section>`;}
function inspections(el){el.innerHTML=pageStart('inspections')+titleblock('COORDINATED INSPECTIONS','Joint Inspection Scheduler','Coordinate a proposed visit across authorities. Scheduling is simulated.')+`<div class="noticebar gold">No inspection request is sent. Confirm the inspection process, authority participation and availability through official channels.</div><div class="grid two section"><section class="card card-pad"><h2>Propose an inspection slot</h2><form id="inspection-form" class="section"><label class="field">Project<select><option>Chemical Manufacturing Unit · Pune</option><option>Artisan Bakery · Pune</option></select></label><label class="field section">Proposed date<input type="date" value="2026-10-07" min="2026-09-27"></label><label class="field section">Site address<input value="Plot 18, Chakan MIDC, Pune, Maharashtra"></label><label class="field section">Participating authorities</label><div class="checkrow">${['MPCB','Fire Services','Factories','PESO'].map((x,i)=>`<label class="checkitem"><input type="checkbox" ${i<3?'checked':''}> ${x}</label>`).join('')}</div><label class="field section">Inspection purpose<textarea>Joint site readiness review for project approval coordination.</textarea></label><button class="btn primary section">Save proposed slot</button></form></section><section>${panel('Pending coordination requests',`<div class="card-pad"><div class="docrow"><div><strong>Chemical Manufacturing Unit</strong><small>Proposed: 07 Oct 2026 · Chakan MIDC</small><small>Authorities: MPCB, Fire Services, Factories</small></div>${badge('Draft','amber')}</div><div class="noticebar">The participating departments must confirm availability. This prototype does not reserve an official appointment.</div></div>`)}</section></div>`;}
function riskPage(el){el.innerHTML=pageStart('risk')+titleblock('RISK-BASED SCRUTINY','Project Risk Assessment','Explainable review indicators from the fictional project profile.')+`<div class="noticebar gold">Risk indicators support review planning in this demonstration. They must not automatically reject, delay or determine an applicant’s entitlement.</div><div class="grid two section"><section class="card card-pad"><div style="display:flex;justify-content:space-between"><div><div class="eyebrow">DEMO PROJECT</div><h2>Mukesh Chemicals Pvt. Ltd.</h2></div>${badge('HIGH REVIEW COMPLEXITY','red')}</div><div class="riskmeter"><span class="riskmarker" style="left:82%"></span></div><div class="keyval"><span>Indicator level</span><strong>High · human review recommended</strong></div><div class="keyval"><span>Project scale</span><strong>₹35 Crore · 150 employees</strong></div><div class="keyval"><span>Process category</span><strong>Red · applicant declared</strong></div><div class="keyval"><span>Unresolved conditions</span><strong>Document and prerequisite checks pending</strong></div><div class="noticebar">The indicator summarises declared demo attributes. It does not represent an official risk score.</div></section><section class="card"><div class="card-head"><h2>Risk factors and evidence</h2></div>${[['Chemical manufacturing','Sector-level review complexity','Declared project profile'],['Red category','Applicant-selected pollution class','Requires authority verification'],['Investment scale','₹25–50 Crore band','Applicant-provided range'],['Process effluent','Potential consent requirements','Verify project process'],['Missing document','Fire plan needs a signature check','Demo vault metadata']].map(x=>`<div class="docrow"><div><strong>${x[0]}</strong><small>${x[1]} · ${x[2]}</small></div>${badge('Review factor','amber')}</div>`).join('')}</section></div><section class="section">${panel('Low-risk comparison · Rahul Foods',`<div class="card-pad grid two"><div><h3>Rahul Foods · Artisan Bakery</h3><p>Small business · Pune · Green category · lower review complexity</p></div><div><div class="riskmeter"><span class="riskmarker" style="left:19%"></span></div>${badge('LOW COMPLEXITY','green')}<p class="subtitle">Fewer conditional industrial approvals are shown in the demo scenario. The actual approval list still depends on location, premises and activity.</p></div></div>`,btn('Switch to Rahul Foods example','switch-rahul','btn'))}</section>`;}
function precedent(el){const rows=[['MPCB CTE','Chemical Manufacturing','Pune','12.4 days','86','Document completeness'],['Fire NOC','Industrial unit','Pune','8.4 days','64','Inspection readiness'],['Factory Licence','Chemical Manufacturing','Maharashtra','16.1 days','52','Plan approval dependency'],['Building Plan','Industrial premises','Pune','11.8 days','78','Application revision']];el.innerHTML=pageStart('precedent')+titleblock('HISTORICAL PROCESSING REFERENCE','Precedent Engine','Comparable-case summaries for operational planning. Sample data only.')+`<div class="noticebar gold">All durations and case counts are synthetic. No government historical application data is connected, and past cases do not guarantee future processing time.</div><div class="grid three section">${stat('Illustrative cases','280','Synthetic records')}${stat('Median processing','12.4 days','Not official service data')}${stat('Reapplication rate','8.2%','Synthetic scenario')}</div>${panel('Comparable approval records',table(['APPROVAL','SECTOR / CONTEXT','JURISDICTION','MEDIAN TIME','SAMPLE CASES','COMMON DELAY FACTOR'],rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')))}<div class="section grid two">${card('How this could work in production',`<p>Compare cases by authority, approval type, project attributes, completeness and effective rule version. Report distributions and confidence intervals. Separate applicant wait time from department processing time.</p>`)}${card('Current project comparison',`<p>MPCB CTE estimate: <strong>12–18 working days</strong></p><p>Sample median: <strong>12.4 days</strong></p><p class="noticebar gold">Both are fictional examples. The sample does not predict a statutory service deadline.</p>`)}</div>`;}
function government(el){el.innerHTML=pageStart('government')+titleblock('OFFICER WORKSPACE','Department Operations','Maharashtra industrial approvals · Regional view: Pune')+`<div class="noticebar">Department metrics and applications are synthetic sample records. Applicant documents are not displayed in this officer overview.</div><div class="grid four section">${stat('TOTAL APPLICATIONS','184','All fictional departments')}${stat('PENDING','37','Across sample queues')}${stat('SLA AT RISK','8','Requires attention','highlight')}${stat('SLA BREACHED','4','Officer review required','')}</div><div class="grid two section"><div>${panel('Operations at a glance',`<div class="card-pad">${departments.slice(0,4).map(d=>`<div class="barrow"><strong>${d.name}</strong><div class="bar"><span class="${d.breaches?'bad':''}" style="width:${Math.min(d.pending*8,100)}%"></span></div><span>${d.pending} pending</span></div>`).join('')}</div>`,hlink('analytics','View performance →','linkbtn'))}</div><div>${panel('Priority applications',`<div class="card-pad">${govRows.filter(r=>r.risk==='HIGH').slice(0,3).map(r=>`<div class="docrow"><div><strong>${r.approval} · ${r.id}</strong><small>${r.applicant} · ${r.days}/${r.sla} days</small></div>${badge(r.status,r.days>=r.sla?'red':'amber')}</div>`).join('')}</div>`,hlink('smartqueue','Open Smart Queue →','linkbtn'))}</div></div><div class="section">${panel('Department Integration',`<div class="card-pad grid three"><div><strong>NSWS</strong><p>${badge('Reference only','gray')}</p><small>Portal link available · No API connector in prototype</small></div><div><strong>MAITRI Maharashtra</strong><p>${badge('Reference only','gray')}</p><small>Portal link available · No API connector in prototype</small></div><div><strong>Reverse Integration</strong><p>${badge('Concept','amber')}</p><small>Department keeps current case-management system; status updates flow back through an authorised adapter.</small></div></div>`,hlink('integration','Integration details →','linkbtn'))}</div><div class="section grid two">${card('Department accountability',`<p>Department-level queues show pending work, service-time distributions, queries and reapplications. Performance data should be contextualised before operational comparisons.</p>${btn('Open bottleneck analytics','route-analytics','btn')}`)}${card('Applicant context',`<p>Review an application in the context of the applicant’s complete project roadmap and related prerequisites.</p>${btn('Open Mukesh Chemicals profile','route-applicant','btn primary')}`)}</div>`;}
function filteredQueue(){let rows=[...govRows];if(state.queueSearch)rows=rows.filter(x=>Object.values(x).join(' ').toLowerCase().includes(state.queueSearch.toLowerCase()));if(state.queueFilter==='SLA risk')rows=rows.filter(x=>x.days>=x.sla*.8);if(state.queueFilter==='MPCB')rows=rows.filter(x=>x.dept==='MPCB');if(state.queueFilter==='Via Agent')rows=rows.filter(x=>x.viaAgent);if(state.queueSort==='oldest')rows.sort((a,b)=>b.days-a.days);else if(state.queueSort==='risk')rows.sort((a,b)=>(b.risk==='HIGH'?2:b.risk==='NORMAL'?1:0)-(a.risk==='HIGH'?2:a.risk==='NORMAL'?1:0));else rows.sort((a,b)=>a.approval.localeCompare(b.approval));return rows;}
function queuePage(el){const rows=filteredQueue();el.innerHTML=pageStart('queue')+titleblock('DEPARTMENT WORKSPACE','My Queue','Review applications assigned to the selected department.',btn('Export queue','export-queue','btn'))+`<div class="noticebar">Prioritisation assists officer workflow. PRAGATI does not reject or dispose of an application because it remains pending.</div><div class="grid four section">${stat('Assigned','37','Sample pending records')}${stat('SLA risk','8','Near sample threshold')}${stat('Queries awaiting reply','6','Fictional records')}${stat('Review today','12','Suggested attention')}</div><div class="tabs section">${['All applications','SLA risk','MPCB','Via Agent'].map(x=>`<button class="tab ${state.queueFilter===x?'active':''}" data-queue-filter="${x}">${x==='Via Agent'?`✦ Via Agent (${govRows.filter(r=>r.viaAgent).length})`:x}</button>`).join('')}</div><div class="grid two"><label class="field">Search queue<input id="queue-search" value="${esc(state.queueSearch)}" placeholder="Application ID, applicant, approval"></label><label class="field">Sort by<select id="queue-sort"><option value="risk" ${state.queueSort==='risk'?'selected':''}>SLA risk</option><option value="oldest" ${state.queueSort==='oldest'?'selected':''}>Oldest pending</option><option value="type" ${state.queueSort==='type'?'selected':''}>Application type</option></select></label></div><section class="card section">${panel(`My Queue · ${rows.length} records`,table(['APPLICATION ID','APPLICANT','BUSINESS','APPROVAL','RECEIVED','DAYS PENDING','SLA','RISK','STATUS',''],rows.map(r=>`<tr><td><button class="linkbtn" data-applicant="${r.id}"><strong>${r.id}</strong></button></td><td>${r.applicant}</td><td>${r.business}</td><td>${r.approval}<small>${r.dept}</small></td><td>${r.received}</td><td>${r.days} days</td><td>${r.sla} days</td><td>${badge(r.risk,r.risk==='HIGH'?'red':r.risk==='LOW'?'green':'amber')}</td><td>${badge(r.status,r.days>=r.sla?'red':r.status==='Under Review'?'blue':'amber')}</td><td>${btn('Prioritise',`prioritise:${r.id}`,'btn small')}</td></tr>`).join('')))}</section><div class="section">${panel('Officer priority rule',`<div class="card-pad"><p>Suggested priority combines time in department, SLA proximity, application risk indicator and downstream dependency impact. The officer retains control over review order and decision-making.</p><div class="statusline">${badge('CRITICAL · breach imminent','red')}${badge('HIGH · near SLA threshold','amber')}${badge('NORMAL · within SLA','blue')}</div></div>`)}</div>`;}
function applicantProfile(el){el.innerHTML=pageStart('applicant')+titleblock('APPLICANT CONTEXT','Mukesh Chemicals Pvt. Ltd.','Where is this applicant’s complete project journey waiting?',btn('Open full roadmap','route-roadmap','btn primary'))+`<div class="grid four">${stat('Applicant','Mukesh Sharma','Managing Director')}${stat('Project','Chemical Unit','Pune, Maharashtra')}${stat('Approvals','17','Identified in demo')}${stat('Risk indicator','HIGH','Complexity review marker')}</div><div class="noticebar gold section">Applicant fields are fictional. This officer view exposes a profile summary for the demo. Production use would require authenticated role permissions and defined processing purposes.</div><section class="section card"><div class="card-head"><h2>Where is this applicant stuck?</h2><span class="critical-tag">CRITICAL PATH</span></div><div class="card-pad grid three">${[['Land verification','Approved','green'],['Building Plan','Approved','green'],['MPCB CTE','Under review · 12/15 days','amber'],['Factory Plan','Ready to start','blue'],['Factory Licence','Blocked by plans + inspection','gray'],['Fire NOC','Blocked by Building Plan','gray'],['Joint inspection','Waiting for CTE + Factory Plan','gray'],['Operational readiness','Waiting on clearance set','gray'],['Document: Fire Safety Plan','Signature field needs attention','red']].map(x=>`<button class="approval-tile" ${{'Land verification':'data-node="land"','Building Plan':'data-node="factory-plan"','MPCB CTE':'data-node="cte"','Factory Plan':'data-node="factory"','Factory Licence':'data-node="licence"','Fire NOC':'data-node="fire"','Joint inspection':'data-node="inspection"','Operational readiness':'data-node="final"'}[x[0]]||'data-doc-detail="Fire Safety Plan"'}><strong>${x[0]}</strong><small>${x[1]}</small><span class="section">${badge(x[1],x[2])}</span></button>`).join('')}</div></section><div class="section grid two">${card('Application progression',`<div class="progressbar"><span style="width:47%"></span></div><p>8 of 17 approvals marked complete in the sample project history.</p><p>Open applications: 8 · pending departments: 6 · dependency-blocked: 3</p>`)}${card('Officer actions',`<p>Review the current CTE queue record, outstanding applicant document and linked approval dependencies.</p>${btn('Open application queue','route-queue','btn')}${btn('View SLA history','route-sla','btn section')}`)}</div>`;}
function analytics(el){el.innerHTML=pageStart('analytics')+titleblock('OPERATIONAL INTELLIGENCE','Department Performance','Service time, backlog, SLA breaches and reapplications · synthetic sample data')+`<div class="noticebar gold">Values below are fabricated to demonstrate analysis layout. Do not cite them as official Maharashtra department performance.</div><div class="grid four section">${stat('Applications in sample','169','Across six sample departments')}${stat('Mean processing','13.1 days','Illustrative cohort')}${stat('SLA breaches','6','Synthetic record count')}${stat('Reapplications','21','Synthetic record count')}</div><section class="section card">${panel('Department performance',table(['DEPARTMENT','APPLICATIONS','AVERAGE TIME','PENDING','SLA BREACHES','REAPPLICATIONS'],departments.map(d=>`<tr><td><strong>${d.name}</strong></td><td>${d.apps}</td><td>${d.avg} days</td><td>${d.pending}</td><td>${badge(String(d.breaches),d.breaches>1?'red':d.breaches?'amber':'green')}</td><td>${d.reapps}</td></tr>`).join('')))}</section><section class="section grid two"><div>${panel('Average time by department',`<div class="card-pad">${departments.map(d=>`<div class="barrow"><strong>${d.name}</strong><div class="bar"><span class="${d.avg>15?'warn':''}" style="width:${d.avg/20*100}%"></span></div><span>${d.avg} days</span></div>`).join('')}</div>`)}</div><div>${panel('Bottleneck map',`<div class="card-pad"><div class="map-grid">${departments.map(d=>`<div class="map-cell ${d.breaches>1?'hot':d.avg>13?'warm':''}"><strong>${d.name}</strong><span>${d.avg}d avg · ${d.pending} pending · ${d.breaches} breach</span></div>`).join('')}</div><p class="subtitle section">Highlighted stages have longer sample elapsed times or higher sample SLA breach counts.</p></div>`)}</div></section><div class="section">${panel('Operational interpretation',`<div class="card-pad"><p>High pending count can result from inbound volume as well as processing time. Inspect application mix, dependency waits, applicant response time and review complexity before setting a capacity or escalation target.</p></div>`)}</div>`;}
function smartQueue(el){queuePage(el);const headEl=el.querySelector('h1');if(headEl)headEl.textContent='Smart Queue';const subtitle=el.querySelector('.subtitle');if(subtitle)subtitle.textContent='Priority suggestions use SLA proximity, time pending, risk and dependency impact. An officer makes every decision.';}
function publicPage(el){const depts=['MPCB','Fire Services','Factories','Planning','MIDC'];el.innerHTML=pageStart('public')+titleblock('PUBLIC TRANSPARENCY','Department Performance — Maharashtra','Aggregate operational indicators for public visibility.')+`<div class="noticebar">Fictional public dashboard for this prototype. Aggregates below are sample data and do not describe actual public applications or departments. Applicant information is not displayed.</div><div class="grid four section">${stat('Applications received','1,284','Synthetic sample')}${stat('Applications approved','926','Synthetic sample')}${stat('Applications pending','358','Synthetic sample')}${stat('Average approval time','11.6 days','Synthetic sample')}</div><section class="section card">${panel('Department-wise performance',table(['DEPARTMENT','APPLICATIONS RECEIVED','APPROVED','PENDING','AVERAGE TIME','SLA WITHIN LIMIT'],depts.map((d,i)=>`<tr><td>${d}</td><td>${[314,231,208,287,244][i]}</td><td>${[233,194,151,207,141][i]}</td><td>${[81,37,57,80,103][i]}</td><td>${[14.2,8.4,16.1,11.8,9.2][i]} days</td><td>${[92,98,87,94,96][i]}%</td></tr>`).join('')))}</section><div class="section grid two">${card('Privacy and aggregation',`<p>The production design should suppress small cohorts and avoid exposing any applicant identity, precise project location or sensitive case detail.</p>`)}${card('Data definitions',`<p>Show reporting period, approval cohort, date of last refresh, exclusions and denominator for every published metric. Sample values shown here are placeholders.</p>`)}</div>`;}
function notificationsPage(el){el.innerHTML=pageStart('notifications')+titleblock('NOTIFICATION CENTRE','Notifications','Project alerts and application updates.',btn('Mark all as read','read-all','btn'))+`<div class="tabs">${['All','Unread'].map(x=>`<button class="tab ${state.notifFilter===x||(!state.notifFilter&&x==='All')?'active':''}" data-notif-filter="${x}">${x}</button>`).join('')}</div><section class="card">${(state.notifFilter==='Unread'?state.notifications.filter(n=>!n.read):state.notifications).map(n=>`<div class="docrow"><div><button class="linkbtn" data-route="${n.route}"><strong>${esc(n.text)}</strong></button><small>${esc(n.time)} · ${n.read?'Read':'Unread'}</small></div>${badge(n.kind==='warning'?'Action required':n.kind==='risk'?'SLA risk':'Update',n.kind==='risk'?'red':n.kind==='warning'?'amber':'blue')}<button class="linkbtn" data-action="notification-read" data-notification="${n.id}">${n.read?'Read':'Mark read'}</button></div>`).join('')||'<div class="empty">No unread notifications.</div>'}</section>`;}
function renewals(el){const rows=[['Fire NOC','Maharashtra Fire Services','28 Nov 2026','62','Review supporting fire safety plan'],['MPCB Consent','Maharashtra Pollution Control Board','15 Dec 2026','79','Confirm operating conditions'],['Factory Licence','Directorate of Industrial Safety','15 Jan 2027','110','Prepare annual returns'],['Boiler Certificate','Directorate of Steam Boilers','20 Feb 2027','146','Check inspection requirements']];el.innerHTML=pageStart('renewals')+titleblock('COMPLIANCE AFTERCARE','Renewals & Compliance','Track certificate dates and prepare upcoming renewal actions.')+`<div class="noticebar gold">Renewal dates and reminders are sample project records. Confirm the current validity, renewal route and statutory deadlines with the issuing authority.</div><div class="grid four section">${stat('Renewals due this quarter','2','Sample project dates')}${stat('Compliance actions','4','Illustrative checklist')}${stat('Expiring documents','1','Within 30 days')}${stat('Next deadline','28 Nov 2026','Fire NOC')}</div><section class="section card">${panel('Renewal register',table(['APPROVAL / CERTIFICATE','ISSUING AUTHORITY','EXPIRY / RENEWAL DUE','TIME REMAINING','PREPARATION',''],rows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${badge(r[3]+' days',Number(r[3])<30?'amber':'blue')}</td><td>${r[4]}</td><td>${btn('Start Renewal',`renew:${r[0]}`,'btn small')}</td></tr>`).join('')))}</section><section class="section">${panel('Business Aftercare',`<div class="grid four card-pad">${['Operational status','Employment','Compliance','Feedback'].map(x=>`<div><strong>${x}</strong><p class="subtitle">Project information available for review</p>${badge('Update profile','gray')}</div>`).join('')}</div>`)}</section>`;}
function knowledge(el){const items=[['MPCB CTE document requirements','Pollution / Maharashtra','MPCB portal','20 Sep 2026','Human Verified'],['Fire NOC renewal process','Fire / Maharashtra','Maharashtra Fire Services','15 Sep 2026','Human Verified'],['Maharashtra industrial incentive references','Schemes / Maharashtra','MAITRI portal','02 Aug 2026','Review due'],['Factory plan application requirements','Factories / Maharashtra','Directorate of Industrial Safety','18 Sep 2026','Human Verified'],['PESO site approval requirements','PESO / Central','PESO portal','12 Sep 2026','Human Verified']];el.innerHTML=pageStart('knowledge')+titleblock('ADMINISTRATION','Regulatory Knowledge Base','Source-controlled information for approval requirements and scheme discovery.',btn('＋ Add record','kb-add','btn'))+`<div class="noticebar gold">AI may assist with retrieval and change detection. An authorised human reviewer must verify regulatory updates before they become active. Records below are sample metadata.</div><div class="grid four section">${stat('Approval metadata','148','Synthetic catalogue')}${stat('Document requirements','512','Synthetic catalogue')}${stat('Scheme records','63','Synthetic catalogue')}${stat('Review due','4','Sample queue')}</div><div class="tabs section">${['Government Rules','Approval Metadata','Document Requirements','Scheme Data','Department Information','Processing Data'].map(x=>`<button class="tab ${state.kbTab===x||(!state.kbTab&&x==='Approval Metadata')?'active':''}" data-kb-tab="${x}">${x}</button>`).join('')}</div><section class="card">${panel('Knowledge records',table(['RECORD','JURISDICTION','SOURCE','LAST UPDATED','VERIFIED BY','STATUS',''],items.map((r,i)=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${i===2?'Awaiting reviewer':'Authorised reviewer'}</td><td>${badge(r[4],i===2?'amber':'green')}</td><td>${btn('Review',`kb-review:${i}`,'linkbtn')}</td></tr>`).join('')))}</section><section class="section card">${panel('Human-in-the-loop regulatory updates',`<div class="card-pad grid four">${[['01','Update detected','Official source monitor'],['02','Change extracted','AI-assisted comparison'],['03','Human reviewer','Verify source + effective date'],['04','Published version','Flag affected workflows']].map(([i,t,d])=>`<div class="roadmap-stat"><span class="eyebrow">STEP ${i}</span><strong style="font-size:16px;display:block">${t}</strong><small>${d}</small></div>`).join('')}</div>`)}</section>`;}
function integration(el){el.innerHTML=pageStart('integration')+titleblock('CONNECTIVITY','Department Integration','A connector layer above existing government platforms.')+`<div class="noticebar gold">The integration indicators below describe the product concept. No NSWS, MAITRI or department API connection is active in this prototype.</div><div class="grid three section">${[['NSWS','Single-window approval discovery','Reference portal · link only'],['MAITRI Maharashtra','State single-window workflow','Reference portal · link only'],['Department system','Existing case-management platform','Reverse Integration concept']].map(([n,d,s])=>`<article class="card card-pad"><div style="display:flex;justify-content:space-between"><h2>${n}</h2>${badge('Not connected','gray')}</div><p>${d}</p><p class="subtitle">${s}</p>${n==='NSWS'?'<a href="https://www.nsws.gov.in/" target="_blank" rel="noopener">Open portal ↗</a>':n.startsWith('MAITRI')?'<a href="https://maitri.maharashtra.gov.in/" target="_blank" rel="noopener">Open portal ↗</a>':'<div class="noticebar">Department continues using its existing workflow. Relevant status updates can be reflected through an authorised, authenticated interface.</div>'}</article>`).join('')}</div><section class="section">${panel('Reverse Integration pattern',`<div class="card-pad grid four">${[['Department case system','Existing record remains authoritative'],['Connector adapter','Authenticated status polling / webhook'],['Event validation','Identity, signature, timestamp, deduplication'],['Orchestration update','Applicant roadmap and SLA projection']].map(([a,b],i)=>`<div class="roadmap-stat"><span class="eyebrow">${i+1}</span><strong style="display:block;font-size:14px">${a}</strong><small>${b}</small></div>`).join('')}</div>`)}</section><section class="section">${panel('Production integration prerequisites',`<div class="card-pad"><ul><li>Written department agreement and supported API or secure event feed</li><li>Clear system of record and correction path for conflicting status</li><li>Service identity, scoped authorisation, event signature and idempotency</li><li>Retry, reconciliation, monitoring and audit requirements</li><li>Applicant consent and data minimisation for cross-department profile visibility</li></ul></div>`)}</section>`;}
function chatbox(){return `<aside class="chatbox"><div class="chat-head"><div><strong>✦ PRAGATI Agent Mode</strong><small style="display:block;color:#d8e7f4">Approval navigation assistant</small></div><button class="icon-btn" data-action="chat-close" aria-label="Close assistant">×</button></div><div class="chat-log" id="chat-log">${(state.chatHistory||[]).map(m=>`<div class="chat-bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}<div class="chat-bubble">I can help you navigate approvals, documents, deadlines and scheme sources. Answers use this project’s sample workflow and verified-source labels.</div><div class="pills">${['What approvals do I need?','Why is this blocked?','What document is missing?','Which approvals can I apply for now?','Why is this taking so long?','When do I renew Fire NOC?','Show Maharashtra schemes'].map(q=>`<button class="tab" data-prompt="${q}">${q}</button>`).join('')}</div></div><form class="chat-input" id="chat-form"><input name="q" maxlength="300" placeholder="Ask about your approval journey"><button class="btn primary small">Ask</button></form></aside>`;}
function openDrawer(content){state.drawer=content;const root=$('#portal-drawer');if(root)root.innerHTML=`<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer">${content}</aside>`;}
function closeDrawer(){state.drawer=null;$('#portal-drawer').innerHTML='';}
function showModal(title,body,actions=''){state.modal={title,body,actions};$('#portal-modal').innerHTML=`<div class="overlay" data-action="modal-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button data-action="modal-close" style="float:right;border:0;background:none;font-size:20px">×</button><div class="eyebrow">PRAGATI · PROTOTYPE</div><h2 style="margin-top:7px">${title}</h2>${body}<div class="actions section">${actions}</div></section></div>`;}
function docDetail(name){const known=state.documents.find(d=>d.name.toLowerCase().includes(name.toLowerCase().split(' ')[0]));const status=known?.status||'Not uploaded';const source=known?'Applicant-provided sample file':'Obtain from a licensed architect, company records or the issuing department as applicable.';showModal(name,`<div class="keyval"><span>Where do I get this?</span><strong>${source}</strong></div><div class="keyval"><span>Status</span><strong>${status}</strong></div><div class="keyval"><span>Source</span><strong>${known?'Applicant document vault':'Official department requirements'}</strong></div><div class="drawer-section"><h3>Prototype checks</h3><p>${known?.verified?'✓ File metadata present<br>✓ Sample field match<br>✓ Current expiry metadata':'○ No file in sample vault<br>○ Field extraction not available'}</p><p class="noticebar gold">The checks shown are illustrative. This is not a statutory document acceptance decision.</p></div>`,`${btn('View Document','view-doc','btn')}${btn('Replace','upload-doc','btn')}${btn('See Requirements','route-help','btn primary')}`);}
function applicantDetail(id){const app=govRows.find(x=>x.id===id);if(!app)return;const focused=state.project==='rahul';const critical=approvals.filter(a=>(focused?['land','factory-plan','fire']:['land','factory-plan','cte','licence','final']).includes(a.id));openDrawer(`<div class="drawer-head"><button class="icon-btn" data-action="close-drawer">×</button><div class="eyebrow">APPLICATION CONTEXT · ${app.dept}</div><h2>${app.approval}</h2>${badge(app.status,app.days>=app.sla?'red':'amber')}</div><div class="drawer-body"><div class="drawer-section"><h3>${app.applicant}</h3><div class="keyval"><span>Applicant</span><strong>${app.person}</strong></div><div class="keyval"><span>Project</span><strong>${app.business} · Pune</strong></div><div class="keyval"><span>Application ID</span><strong>${app.id}</strong></div><div class="keyval"><span>Days pending</span><strong>${app.days} / ${app.sla} day sample SLA</strong></div><div class="keyval"><span>Risk</span>${badge(app.risk,app.risk==='HIGH'?'red':'green')}</div></div><div class="drawer-section"><h3>Where is this applicant stuck?</h3><div class="timeline">${critical.map(a=>`<div class="timeline-item"><small>${state.approved.includes(a.id)?'COMPLETE':a.id==='cte'?'CURRENT REVIEW':'NEXT / WAITING'}</small><strong>${a.name}</strong><p>${a.dept}</p></div>`).join('')}</div></div><div class="drawer-section"><h3>Officer actions</h3>${btn('Add review note','review-note','btn')}${btn('Update sample status','officer-status','btn section')}${btn('Open full applicant context','route-applicant','btn primary section')}</div><p class="noticebar gold">Fictional case and applicant. Status update changes only this local prototype.</p></div>`);}
function chatAnswer(q){const s=q.toLowerCase();if(s.includes('parallel')||s.includes('ready')){const ready=approvals.filter(a=>derivedStatus(a)==='Ready to Apply');return `You currently have ${Math.max(ready.length,5)} approvals shown as ready in the sample roadmap. MPCB CTE, Factory Plan, Water Connection, PESO and Factory Licence may appear together where their prerequisites allow. Your graph shows the current state and any dependency blocks. These conditions are illustrative.`;}if(s.includes('block'))return 'Factory Licence is waiting for Factory Plan approval and Building Plan Approval. Fire NOC also needs an approved building plan. MPCB CTO waits for MPCB CTE and the project plan. Open the roadmap node to see each prerequisite.';if(s.includes('missing')||s.includes('document'))return 'The Fire Safety Plan in your sample vault needs a signature check. The MPCB CTE checklist also needs a pollution control proposal. Open My Documents to review sample validations or choose a document on the roadmap to see its source.';if(s.includes('long')||s.includes('delay'))return 'Building Plan Approval is 2 sample days beyond its 15-day SLA. MPCB CTE is at 12 of 15 sample days. The current project may wait on those approvals before dependent reviews can start. No official service clock is connected.';if(s.includes('renew')||s.includes('fire noc'))return 'The sample Fire NOC record expires on 28 November 2026. That is 62 calendar days after the prototype reference date of 27 September, while the sample alert list uses a separately prepared 18-day warning. Confirm the actual certificate and renewal window with Fire Services.';if(s.includes('scheme'))return 'The Schemes page links to NSWS and MAITRI discovery sources. Five sample programme categories are listed for research, but their current status and eligibility have not been verified.';if(s.includes('approval'))return 'For the current chemical project, the sample catalogue contains 17 approval and registration nodes. Five independent reviews are marked ready to begin in the seeded scenario. The KYA flow explains the fields; the roadmap shows which can proceed and what is blocked.';return 'I can help explain the approval graph, missing documents, sample SLA clocks or scheme discovery. Answers here use a small local rule set and fictional project records, not a connected government service.';}
function addChat(q){q=q.trim();if(!q)return;state.chatHistory.push({role:'user',text:q},{role:'assistant',text:chatAnswer(q)});state.chatHistory=state.chatHistory.slice(-16);persist();const old=$('#chatbox-root');if(!old){state.chatOpen=true;render();}else{const log=$('#chat-log');log.innerHTML=state.chatHistory.map(m=>`<div class="chat-bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')+`<div class="pills">${['Open Roadmap','View Missing Documents','Apply Now','Show Maharashtra schemes'].map((x,i)=>`<button class="tab" data-chat-route="${['roadmap','documents','application','schemes'][i]}">${x}</button>`).join('')}</div>`;log.scrollTop=log.scrollHeight;bindGlobal();}}
function documentUpload(){showModal('Upload a document',`<form id="upload-form"><label class="field">Select a sample document<input id="upload-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" required></label><label class="field section">Document type<select id="upload-type"><option>Project Report</option><option>Pollution Control Proposal</option><option>Fire Safety Plan</option><option>Site Plan</option><option>Entity Certificate</option><option>Other</option></select></label><label class="field section">Expiry date, if applicable<input type="date" id="upload-expiry"></label><p class="noticebar">Local demo only. The selected file is not uploaded to a server. OCR and rule checks below are simulated.</p><button class="btn primary section">Run validation</button></form>`);}
function runUpload(form){const file=$('#upload-file').files?.[0];if(!file){toast('Choose a demonstration file first.');return;}const type=$('#upload-type').value,expiry=$('#upload-expiry').value;$('#portal-modal').innerHTML=`<div class="overlay"><section class="modal"><div class="eyebrow">DOCUMENT INTELLIGENCE</div><h2>AI + OCR Validation</h2><p>Inspecting ${esc(file.name)}…</p><div class="progressbar section"><span style="width:85%"></span></div></section></div>`;setTimeout(()=>{const id='doc-'+Date.now(),issue=type==='Fire Safety Plan';state.documents.unshift({id,name:`${type} — ${file.name}`,type,uploaded:'27 Sep 2026',status:issue?'Needs attention':'Verified',expiry:expiry||'No expiry',uses:1,verified:!issue,issue:issue?'Signature field was not detected. Review the signature area before submission.':''});state.modal=null;persist();render();toast(issue?'Validation complete: signature check needs attention.':'Validation complete: metadata checks passed.');},1100);}
function escalation(){showModal('Escalation draft',`<p>Draft an operational note for authorised review. This action does not contact a department or send a message.</p><label class="field">Application<textarea id="escalation-text">MH-BP-20496 · Building Plan Approval — 17 days pending against the 15-day sample SLA. Please review current status and applicant-side dependencies.</textarea></label><p class="noticebar gold">Sample draft includes synthetic case details. No communication is sent.</p>`,`${btn('Copy draft','copy-escalation','btn')}${btn('Close','modal-close','btn primary')}`);}
function queueAction(id){const app=govRows.find(a=>a.id===id);if(!app)return;showModal(`Prioritise ${app.id}`,`<p><strong>${app.applicant}</strong> · ${app.approval}</p><p>${app.days} days pending against ${app.sla} sample SLA days. Risk indicator: ${app.risk}.</p><p>Priority suggestions consider SLA proximity, elapsed time, application risk and downstream dependency impact. The assigned officer makes the decision.</p><label class="field">Priority reason<select><option>SLA proximity</option><option>Dependency impact</option><option>Applicant query</option><option>Officer judgement</option></select></label>`,`${btn('Set suggested priority','confirm-priority','btn primary')}${btn('Cancel','modal-close','btn')}`);state.pendingQueueId=id;}
function inspectQuery(aid){showModal('Application SLA details',`<p><strong>${aid}</strong></p><p>Current status from the sample queue is simulated. The illustrative SLA clock is derived from sample intake and update dates.</p><div class="keyval"><span>Escalation</span><strong>Department review and dependency analysis</strong></div><p>No automatic rejection is triggered when an SLA is exceeded.</p>`,btn('Prepare escalation draft','escalation','btn primary'));}
function renewAction(name){showModal(`Start renewal · ${name}`,`<p>This will open a local renewal preparation checklist for the sample certificate.</p><div class="noticebar">Confirm actual renewal availability, documents and deadline with the issuing authority.</div><label class="checkitem section"><input type="checkbox"> I reviewed the sample certificate and expiry date</label>`,btn('Prepare renewal checklist','confirm-renew','btn primary'));state.pendingRenewal=name;}
function reviewKb(i){const items=['MPCB CTE document requirements','Fire NOC renewal process','Maharashtra industrial incentive references','Factory plan application requirements','PESO site approval requirements'];showModal('Human review · regulatory record',`<p><strong>${items[i]}</strong></p><div class="keyval"><span>Source locator</span><strong>Official portal link on record</strong></div><div class="keyval"><span>Current status</span><strong>${i===2?'Review due':'Human Verified · demo record'}</strong></div><label class="field">Review note<textarea placeholder="Record source version and verification notes"></textarea></label><p class="noticebar gold">A verified badge in this prototype is not a real approval of a legal rule. Do not publish updated requirements from an AI extraction without human verification.</p>`,`${btn('Mark review completed','kb-confirm','btn primary')}${btn('Close','modal-close','btn')}`);state.pendingKbIndex=i;}
function resetDemo(){showModal('Reset demonstration data?',`<p>This restores the fictional Mukesh Chemicals applicant, sample roadmap and notifications. The small business scenario remains available. Local prototype data will be replaced.</p>`,`${btn('Reset demo','confirm-reset','btn primary')}${btn('Cancel','modal-close','btn')}`);}
function exportRoadmap(){const content={product:'PRAGATI',prototype:true,generatedAt:new Date().toISOString(),profile:state.profile,assumptions:'Illustrative approvals and timings; confirm with competent authorities.',approvals:approvals.map(a=>({id:a.id,name:a.name,department:a.dept,status:derivedStatus(a),dependencies:a.deps,estimatedDays:a.days,illustrativeSlaDays:a.sla,requiredDocuments:a.docs}))};download('pragati-approval-roadmap.json',JSON.stringify(content,null,2),'application/json');}
function download(name,body,mime){const blob=new Blob([body],{type:mime}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function bindClicks(){document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.classList.contains('overlay')&&e.target!==el)return;const act=el.dataset.action;if(act.startsWith('route-')){location.hash=act.slice(6);return;}if(act==='chat'){state.chatOpen=false;loadRoute('agent');return;}if(act==='chat-close'){state.chatOpen=false;render();return;}if(act==='notifications'){state.route='notifications';state.notifFilter='All';render();return;}if(act==='profile-menu'){state.profileMenu=!state.profileMenu;render();return;}if(act==='role-applicant'){state.role='applicant';state.profileMenu=false;state.route='dashboard';persist();render();toast('Applicant View · Mukesh Chemicals Pvt. Ltd.');return;}if(act==='role-government'){state.role='government';state.profileMenu=false;state.route='government';persist();render();toast('Government / Department View · Officer workspace');return;}if(act==='logout'){state.profileMenu=false;render();toast('This is a prototype. Sign-in is not connected.');return;}if(act==='kya-next'){captureKya();state.kyaStep=Math.min(3,state.kyaStep+1);persist();render();return;}if(act==='kya-back'){captureKya();state.kyaStep=Math.max(0,state.kyaStep-1);persist();render();return;}if(act==='kya-submit'){captureKya();const pollution=state.kyaAnswers?.pollution||'Red';state.profile.pollution=pollution;const industry=state.kyaAnswers?.industry;if(industry==='Food Processing'){state.project='rahul';state.profile={...state.profile,...state.lowProfile};state.approved=['land','factory-plan','electricity','labour'];}else{state.project='mukesh';state.profile={...seed.profile};state.approved=[...seed.approved];}el;showAnalyzing();return;}if(act==='close-drawer'){closeDrawer();return;}if(act==='advance-clock'){state.simulationDay=(state.simulationDay||0)+1;state.events.unshift({title:'Demo SLA clock advanced',detail:`Simulation day ${state.simulationDay}`,time:'27 Sep 2026, just now'});persist();render();toast('Illustrative SLA clock advanced by one day.');return;}if(act==='node-blockers'){closeDrawer();roadmap($('#page'));return;}if(act==='kb-add'){showModal('Add knowledge record',`<p>New regulatory records enter a review queue. An authorised reviewer must verify the source before the record becomes active.</p><label class="field">Record title<input id="kb-title" placeholder="e.g. Boiler registration document checklist"></label><label class="field section">Source<input id="kb-source" placeholder="Official portal or notification"></label>`,`${btn('Submit for review','kb-add-save','btn primary')}${btn('Cancel','modal-close','btn')}`);return;}if(act==='kb-add-save'){const t=($('#kb-title')?.value||'').trim();if(!t){toast('Enter a record title.');return;}state.modal=null;$('#portal-modal').innerHTML='';notify(`Knowledge record "${t}" submitted for human review.`,'knowledge','info');return;}if(act==='reset-demo'){state.profileMenu=false;render();resetDemo();return;}if(act==='doc-detail'){closeDrawer();docDetail(el.dataset.doc||'');return;}if(act==='modal-close'){state.modal=null;$('#portal-modal').innerHTML='';return;}if(act==='upload-doc'){documentUpload();return;}if(act==='view-doc'){showModal('Document preview',`<p>Preview is unavailable for this illustrative metadata record.</p><p class="noticebar">No document contents were transferred or retained by the prototype.</p>`,btn('Close','modal-close','btn primary'));return;}if(act==='simulate-submit'){const id=el.dataset.nodeId||'cte';if(!state.approved.includes(id))state.approved.push(id);persist();closeDrawer();render();notify('Demo application status updated. No department was contacted.','roadmap');return;}if(act==='app-next'){state.appStep=Math.min(5,state.appStep+1);persist();render();return;}if(act==='app-back'){state.appStep=Math.max(0,state.appStep-1);render();return;}if(act==='app-finish'){state.appSubmitted=true;state.events.unshift({title:'Application draft prepared',detail:'MPCB Consent to Establish · local-only record',time:'27 Sep 2026, just now'});persist();render();return;}if(act==='use-verified'){toast('Verified sample fields are already prefilled.');return;}if(act==='upload-doc'){documentUpload();return;}if(act==='save-scheme'){el.textContent='Saved ✓';el.disabled=true;toast('Scheme source saved to this local research session.');return;}if(act==='roadmap-export'){exportRoadmap();return;}if(act==='escalation'){escalation();return;}if(act==='copy-escalation'){navigator.clipboard?.writeText($('#escalation-text')?.value||'').then(()=>toast('Draft copied to clipboard.')).catch(()=>toast('Select and copy the draft text manually.'));return;}if(act==='confirm-priority'){state.priorityList??=[];state.priorityList.push(state.pendingQueueId);state.pendingQueueId=null;$('#portal-modal').innerHTML='';toast('Priority suggestion added to this local view.');return;}if(act==='confirm-renew'){const name=state.pendingRenewal;$('#portal-modal').innerHTML='';notify(`${name} renewal checklist opened in the demo.`,`renewals`,'info');return;}if(act==='confirm-reset'){resetAgent();state.approved=[...seed.approved];state.events=[...seed.events];state.notifications=JSON.parse(JSON.stringify(seed.notifications));state.documents=JSON.parse(JSON.stringify(seed.documents));state.appStep=0;state.appSubmitted=false;state.kyaDone=false;state.simulationDay=0;state.profile={...seed.profile};state.project='mukesh';state.role='applicant';state.kyaStep=0;delete state.kyaAnswers;state.chatHistory=[];state.modal=null;$('#portal-modal').innerHTML='';state.route='home';persist();if(location.hash!=='#home')history.replaceState(null,'','#home');render();window.scrollTo(0,0);toast('Demo data restored.');return;}if(act==='kb-confirm'){const i=state.pendingKbIndex;state.kbVerified??=[];state.kbVerified.push(i);$('#portal-modal').innerHTML='';notify('Review status recorded in the local demo only. No regulatory rule was changed.','knowledge');return;}if(act==='review-note'){showModal('Officer review note',`<label class="field">Internal note<textarea placeholder="Add a concise case note"></textarea></label><p class="subtitle">Local demonstration only. Note is not saved to a departmental system.</p>`,btn('Save local note','modal-close','btn primary'));return;}if(act==='officer-status'){showModal('Update sample status',`<label class="field">New status<select><option>Under Review</option><option>Query Raised</option><option>Ready for Inspection</option><option>Approved</option></select></label><p class="noticebar gold">Changes only the prototype display. A real status must come from the department’s record system.</p>`,btn('Apply sample update','officer-update','btn primary'));return;}if(act==='officer-update'){if(state.drawer){state.approved.push('cte');persist();closeDrawer();render();toast('Local sample status updated.');}$('#portal-modal').innerHTML='';return;}if(act==='notification-read'){const n=state.notifications.find(x=>x.id===Number(el.dataset.notification));if(n)n.read=true;persist();render();return;}if(act==='read-all'){state.notifications.forEach(n=>n.read=true);persist();render();toast('Notifications marked read.');return;}if(act==='switch-rahul'){state.profile={...state.lowProfile};state.project='rahul';state.route='kya';state.kyaStep=0;persist();render();toast('Rahul Foods profile loaded.');return;}if(act==='export-queue'){download('pragati-department-queue.csv','Application ID,Applicant,Approval,Department,Received,Days Pending,SLA,Risk,Status\n'+filteredQueue().map(r=>[r.id,r.applicant,r.approval,r.dept,r.received,r.days,r.sla,r.risk,r.status].join(',')).join('\n'),'text/csv');return;}}
);document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(state.modal||$('#portal-modal')?.innerHTML){state.modal=null;$('#portal-modal').innerHTML='';}else if(state.drawer)closeDrawer();});document.addEventListener('submit',e=>{if(e.target.id==='upload-form'){e.preventDefault();runUpload(e);}});window.addEventListener('hashchange',()=>{const key=location.hash.slice(1)||'home';if(titles[key]){state.route=key;persist();render();}});}
function captureKya(){const f=$('#kya-form');if(!f)return;state.kyaAnswers??={};if(state.kyaStep===0){const v=f.querySelectorAll('select');Object.assign(state.kyaAnswers,{business:v[0]?.value,state:v[1]?.value,district:v[2]?.value,industry:v[3]?.value,stage:v[4]?.value});}else if(state.kyaStep===1){const v=f.querySelectorAll('select');Object.assign(state.kyaAnswers,{size:v[0]?.value,investment:v[1]?.value,employment:v[2]?.value,land:v[3]?.value});}else if(state.kyaStep===2){state.kyaAnswers.pollution=f.querySelector('input[name=pollution]:checked')?.value||'Red';state.kyaAnswers.requirements=[...f.querySelectorAll('input[type=checkbox]')].map(x=>x.checked);}}
function showAnalyzing(){const el=$('#page');el.innerHTML=pageStart('kya')+`<section class="card card-pad" style="max-width:720px;margin:70px auto;text-align:center"><div class="eyebrow">KNOW YOUR APPROVALS</div><h1>Analysing your requirements...</h1><p class="subtitle">Evaluating the structured project profile against the demonstration approval catalogue.</p><div class="progressbar section"><span style="width:100%;animation:pulse 1s infinite alternate"></span></div><p id="analysis-step" class="subtitle section">Checking project characteristics…</p></section>`;setTimeout(()=>{const t=$('#analysis-step');if(t)t.textContent='Building dependency roadmap…';},450);setTimeout(()=>{state.kyaDone=true;state.kyaStep=0;state.route='roadmap';persist();roadmap($('#page'));window.scrollTo(0,0);toast(`Roadmap ready. ${state.project==='rahul'?6:17} illustrative approvals / registrations identified.`);},1000);}
function renderWithState(){if(!titles[state.route])state.route='home';render();}
function bindGlobal(){bindGlobalCore();}
function bindGlobalCore(){document.querySelectorAll('[data-node]').forEach(a=>a.addEventListener('click',()=>nodeDrawer(a.dataset.node)));document.querySelectorAll('[data-route]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const r=a.dataset.route;if(r==='notifications')state.notifications.forEach(n=>n.read=true);if(location.hash==='#'+r)loadRoute(r);else location.hash=r;}));document.querySelectorAll('[data-filter-approvals]').forEach(a=>a.addEventListener('click',()=>{state.approvalFilter=a.dataset.filterApprovals;render();}));document.querySelectorAll('[data-scheme-filter]').forEach(a=>a.addEventListener('click',()=>{state.schemeFilter=a.dataset.schemeFilter;render();}));document.querySelectorAll('[data-doc-filter]').forEach(a=>a.addEventListener('click',()=>{state.docFilter=a.dataset.docFilter;render();}));document.querySelectorAll('[data-queue-filter]').forEach(a=>a.addEventListener('click',()=>{state.queueFilter=a.dataset.queueFilter;render();}));document.querySelectorAll('[data-notif-filter]').forEach(a=>a.addEventListener('click',()=>{state.notifFilter=a.dataset.notifFilter;render();}));document.querySelectorAll('[data-kb-tab]').forEach(a=>a.addEventListener('click',()=>{state.kbTab=a.dataset.kbTab;render();}));document.querySelectorAll('[data-appstep]').forEach(a=>a.addEventListener('click',()=>{state.appStep=+a.dataset.appstep;render();}));document.querySelectorAll('[data-lang]').forEach(a=>a.addEventListener('click',()=>{state.lang=a.dataset.lang;persist();render();toast(`Language set to ${a.textContent}. Translation coverage is partial in this prototype.`);}));document.querySelectorAll('[data-prompt]').forEach(a=>a.addEventListener('click',()=>addChat(a.dataset.prompt)));document.querySelectorAll('[data-chat-route]').forEach(a=>a.addEventListener('click',()=>{state.chatOpen=false;location.hash=a.dataset.chatRoute;}));document.querySelectorAll('[data-applicant]').forEach(a=>a.addEventListener('click',()=>applicantDetail(a.dataset.applicant)));document.querySelectorAll('[data-doc-detail]').forEach(a=>a.addEventListener('click',()=>docDetail(a.dataset.docDetail)));document.querySelectorAll('[data-doc]').forEach(a=>a.addEventListener('click',()=>docDetail(a.dataset.doc)));document.querySelectorAll('[data-action^="node:"]').forEach(a=>a.addEventListener('click',()=>nodeDrawer(a.dataset.action.split(':')[1])));document.querySelectorAll('[data-action^="doc:"]').forEach(a=>a.addEventListener('click',()=>{const d=state.documents.find(x=>x.id===a.dataset.action.split(':')[1]);if(d)docDetail(d.name);}));document.querySelectorAll('[data-action^="sla:"]').forEach(a=>a.addEventListener('click',()=>inspectQuery(a.dataset.action.split(':')[1])));document.querySelectorAll('[data-action^="prioritise:"]').forEach(a=>a.addEventListener('click',()=>queueAction(a.dataset.action.split(':')[1])));document.querySelectorAll('[data-action^="renew:"]').forEach(a=>a.addEventListener('click',()=>renewAction(a.dataset.action.split(':')[1])));document.querySelectorAll('[data-action^="kb-review:"]').forEach(a=>a.addEventListener('click',()=>reviewKb(+a.dataset.action.split(':')[1])));document.querySelectorAll('[data-help]').forEach(a=>a.addEventListener('click',()=>showModal('Field guidance',`<p>${esc(a.dataset.help)}</p><p>Use the value shown in the relevant official company or project record.</p>`,btn('Got it','modal-close','btn primary'))));const search=$('#queue-search');if(search)search.addEventListener('input',()=>{state.queueSearch=search.value;queuePage($('#page'));bindGlobalCore();const x=$('#queue-search');x.focus();x.setSelectionRange(x.value.length,x.value.length);});const sort=$('#queue-sort');if(sort)sort.addEventListener('change',()=>{state.queueSort=sort.value;queuePage($('#page'));bindGlobalCore();});$('#inspection-form')?.addEventListener('submit',e=>{e.preventDefault();notify('Inspection slot saved as a local proposal. Department availability is not confirmed.','inspections','warning');});$('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const q=new FormData(e.target).get('q');addChat(q);e.target.reset();});$('#kya-form')?.addEventListener('submit',e=>{e.preventDefault();});}
// One global action handler keeps navigation and modal actions consistent across modules.
initAgent({getState:()=>state,persist,notify,render,toast,approvals,govRows,derivedStatus,esc,badge,btn,pageStart,showModal,today,titles});bindClicks();window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'home';if(titles[r]){state.route=r;persist();render();}});renderWithState();
